# ------------------------------------------------------------------ 10.11. slot 3: Großglockner Hochalpenstraße (Baugeschichte)
def serpentine(turns, x0, x1, H, W):
    """hairpins on the +z face of a ridge (cross-section: base half width W/2 at y 0, crest at z 0.06 W, y H)"""
    zb, zt = W / 2 * 0.92, W * 0.10
    pts = []
    for i in range(turns + 1):
        z = zb - (zb - zt) * i / turns
        y = H * (W / 2 - z) / (W / 2 - 0.06 * W) + 4
        x = x0 if i % 2 == 0 else x1
        pts.append([x, round(y, 1), round(z, 1)])
        if i < turns:
            z2 = zb - (zb - zt) * (i + 0.5) / turns
            y2 = H * (W / 2 - z2) / (W / 2 - 0.06 * W) + 4
            pts.append([x1 if i % 2 == 0 else x0, round(y2, 1), round(z2, 1)])
    return pts


